const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');
const memoryPath = path.join(userDataDir, 'memory_rules.json');

if (!fs.existsSync(userDataDir)) {
  fs.mkdirSync(userDataDir, { recursive: true });
}

if (!fs.existsSync(registryPath)) {
  fs.writeFileSync(registryPath, JSON.stringify({ trackers: {} }, null, 2), 'utf8');
}

if (!fs.existsSync(memoryPath)) {
  fs.writeFileSync(memoryPath, JSON.stringify({ morning_rules: [], custom_scopes: {} }, null, 2), 'utf8');
}

const trackersRegistry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
const memoryRules = JSON.parse(fs.readFileSync(memoryPath, 'utf8'));

// Purge expired volatile rules automatically
const now = new Date();
const todayIsoDate = now.toISOString().slice(0, 10);
const tomorrowIsoDate = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
let memoryChanged = false;
if (memoryRules.custom_scopes && typeof memoryRules.custom_scopes === 'object') {
  for (const [scopeName, rules] of Object.entries(memoryRules.custom_scopes)) {
    if (Array.isArray(rules)) {
      const filtered = rules.filter((r) => !r.expires_at || r.expires_at >= todayIsoDate);
      if (filtered.length !== rules.length) {
        memoryRules.custom_scopes[scopeName] = filtered;
        memoryChanged = true;
      }
    }
  }
}
if (memoryChanged) {
  fs.writeFileSync(memoryPath, JSON.stringify(memoryRules, null, 2), 'utf8');
}

const body = $input.first().json.body || $input.first().json || {};
const voiceCommand = body.command || body.text || body.query || body.message || '';
const notifyDiscord = body.notify_discord !== undefined ? Boolean(body.notify_discord) : true;

const customViewGuidelines = [
  '### VUES PERSONNALISÉES DE TRACKERS (MICRO-APPS HTML/CSS/JS SANDBOXÉES VIA `update_tracker_custom_view`)',
  'Lorsque l utilisateur demande de créer, modifier ou réinitialiser l affichage visuel d un tracker (onglets, totaux journaliers, recherche/filtres, détails dépliables, duplication 1-clic, graphiques SVG, boutons de cycle) :',
  '- Appelle OBLIGATOIREMENT l outil `update_tracker_custom_view` (`action: "set"`, `tracker_id`, `html`, `css`, `js`) ou passe `custom_view: { html, css, js }` dans `create_or_update_tracker_schema`. Pour revenir à l affichage standard, appelle `update_tracker_custom_view` avec `action: "reset"`.',
  '- **INTERDICTION STRICTE d écrire du code HTML, CSS ou JS dans ta réponse finale à l utilisateur** : exécute l outil `update_tracker_custom_view`, puis confirme simplement en 1 à 2 lignes courtes que la vue personnalisée est enregistrée.',
  '- **Tu écris du vrai HTML + CSS + JavaScript** (rendu dans une `<iframe sandbox="allow-scripts allow-modals">` avec CSP stricte) :',
  '  - N utilise PAS de syntaxe Mustache/Handlebars. Construis et mets à jour le DOM en JavaScript avec `window.jarvis`.',
  '  - N utilise JAMAIS `fetch()`, `XMLHttpRequest`, ni de librairies externes/CDN (bloqués par la CSP).',
  '  - Ne JAMAIS utiliser `window.alert()`, `window.confirm()` ou `window.prompt()` (mauvaise UX mobile et bloqués par défaut en sandbox). Pour confirmer une suppression, utilise un bouton inline en 2 clics ("Supprimer" -> "Confirmer ?") ou une suppression directe + `jarvis.toast(...)`.',
  '  - Ne duplique JAMAIS le titre (`display_name`) déjà affiché par l en-tête de la carte parente.',
  '  - Les entrées supprimées sont déjà filtrées côté serveur dans `jarvis.records`.',
  '  - Utilise exclusivement les noms exacts déclarés dans `fields_schema` du tracker pour lire ou écrire les propriétés de chaque objet dans `jarvis.records`.',
  '  - Sur toutes les lignes `display: flex`, ajoute `flex-wrap: wrap` ou `min-width: 0` pour éviter tout débordement horizontal mobile.',
  '- **Variables CSS de thème obligatoires** (compatibilité automatique Pastel & Crème / Graphite Sombre) :',
  '  `var(--bg-canvas)`, `var(--bg-surface)`, `var(--bg-subtle)`, `var(--border-subtle)`, `var(--text-primary)`, `var(--text-secondary)`, `var(--text-muted)`, `var(--accent-primary)`, `var(--accent-soft)`, `var(--pastel-sage)`, `var(--pastel-sage-soft)`, `var(--pastel-lavender)`, `var(--pastel-lavender-soft)`, `var(--pastel-butter)`, `var(--pastel-butter-soft)`, `var(--pastel-rose)`, `var(--pastel-rose-soft)`.',
  '- **SDK `window.jarvis` disponible dans `js`** :',
  '  - `jarvis.tracker` : `{ id, display_name, type, cycle_config, current_step, fields_schema, record_count }`',
  '  - `jarvis.records` : tableau de toutes les entrées actives (les plus récentes en premier)',
  '  - `jarvis.today` : date locale `' + todayIsoDate + '` (`YYYY-MM-DD`)',
  '  - `jarvis.theme` : `"light" | "dark"`',
  '  - `jarvis.escapeHtml(str)` : échappe proprement une chaîne pour `innerHTML`',
  '  - `await jarvis.addRecord(data)` : crée une entrée (ex. duplication 1-clic ou formulaire rapide) et rafraîchit la vue',
  '  - `await jarvis.updateRecord(recordId, data)` : modifie une entrée existante',
  '  - `await jarvis.deleteRecord(recordId)` : supprime une entrée',
  '  - `await jarvis.mutateCycle(operation, payload)` : `operation` = `"advance_cycle"` ou `"skip_or_shift_cycle"`',
  '  - `jarvis.openDetail(recordId)` : ouvre le panneau de détail complet du tracker dans le dashboard',
  '  - `jarvis.toast(message)` : affiche une notification toast dans le dashboard',
  '  - `jarvis.onUpdate(render)` : ré-exécute `render()` dès que les données ou le thème changent',
  '- **Pattern JS de référence (compact et réactif)** :',
  '  ```js',
  '  const app = document.getElementById("app");',
  '  function render() {',
  '    const rows = (jarvis.records || []);',
  '    app.innerHTML = rows.length ? rows.map(r => `<div class="row">${jarvis.escapeHtml(r.nom || "")}</div>`).join("") : `<div class="empty">Aucune entrée</div>`;',
  '  }',
  '  render();',
  '  jarvis.onUpdate(render);',
  '  ```'
].join('\n');

return [
  {
    json: {
      voice_command: voiceCommand,
      notify_discord: notifyDiscord,
      current_date: todayIsoDate,
      tomorrow_date: tomorrowIsoDate,
      current_timestamp: now.toISOString(),
      trackers_registry: trackersRegistry,
      memory_rules: memoryRules,
      custom_view_guidelines: customViewGuidelines
    }
  }
];

const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');

function sanitizeHtml(raw) {
  return String(raw || '')
    .slice(0, 24576)
    .replace(/<(script|iframe|object|embed|link|meta|base|applet)\b[^>]*>[\s\S]*?<\/\1>/gi, '')
    .replace(/<\/?(script|iframe|object|embed|link|meta|base|applet)\b[^>]*\/?>/gi, '')
    .replace(/(javascript|vbscript|data\s*:\s*text\/html)\s*:/gi, 'blocked:')
    .trim();
}

function sanitizeCss(raw) {
  return String(raw || '')
    .slice(0, 12288)
    .replace(/@import\b[^;]*;?/gi, '')
    .replace(/expression\s*\([^)]*\)/gi, '')
    .replace(/url\s*\(\s*['"]?\s*(https?:|\/\/|javascript:|vbscript:|data\s*:\s*text\/html)[^)]*\)/gi, 'url()')
    .replace(/<\/?style\b[^>]*>/gi, '')
    .trim();
}

function sanitizeJs(raw) {
  return String(raw || '')
    .slice(0, 24576)
    .replace(/<\/?script\b[^>]*>/gi, '')
    .trim();
}

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for create_or_update_tracker_schema', details: err.message });
}

const trackerId = String(payload.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
if (!trackerId) {
  return JSON.stringify({ error: 'tracker_id is required' });
}

const validTypes = ['CYCLE_STATE_MACHINE', 'COLLECTION_TABLE', 'ACTIVITY_LOG'];
const trackerType = validTypes.includes(payload.type) ? payload.type : 'ACTIVITY_LOG';
const nowIso = new Date().toISOString();
const today = nowIso.slice(0, 10);

const registry = fs.existsSync(registryPath)
  ? JSON.parse(fs.readFileSync(registryPath, 'utf8'))
  : { trackers: {} };

if (!registry.trackers) registry.trackers = {};
const existing = registry.trackers[trackerId] || {};

let customView = existing.custom_view || null;
if (payload.custom_view && typeof payload.custom_view === 'object') {
  const cleanJs = sanitizeJs(payload.custom_view.js !== undefined ? payload.custom_view.js : (existing.custom_view?.js || ''));
  if (cleanJs) {
    try {
      new Function('jarvis', cleanJs);
    } catch (syntaxErr) {
      return JSON.stringify({
        status: 'error',
        error: 'Erreur de syntaxe JS dans custom_view.js : ' + syntaxErr.message + '. Corrige le JS et rappelle l outil.'
      });
    }
  }
  customView = {
    enabled: payload.custom_view.enabled !== undefined ? Boolean(payload.custom_view.enabled) : true,
    html: sanitizeHtml(payload.custom_view.html || existing.custom_view?.html || '<div id="app"></div>'),
    css: sanitizeCss(payload.custom_view.css || existing.custom_view?.css || ''),
    js: cleanJs,
    updated_at: nowIso
  };
}

const updatedTracker = {
  display_name: payload.display_name || existing.display_name || trackerId,
  type: trackerType,
  include_in_morning_briefing: payload.include_in_morning_briefing !== undefined
    ? Boolean(payload.include_in_morning_briefing)
    : (existing.include_in_morning_briefing !== undefined ? existing.include_in_morning_briefing : true),
  cycle_config: trackerType === 'CYCLE_STATE_MACHINE'
    ? {
        steps: Array.isArray(payload.cycle_config?.steps) && payload.cycle_config.steps.length > 0
          ? payload.cycle_config.steps
          : (existing.cycle_config?.steps || ['Step 1', 'Rest']),
        current_index: typeof payload.cycle_config?.current_index === 'number'
          ? payload.cycle_config.current_index
          : (existing.cycle_config?.current_index || 0),
        last_updated: payload.cycle_config?.last_updated || existing.cycle_config?.last_updated || today
      }
    : (payload.cycle_config || existing.cycle_config || null),
  fields_schema: Array.isArray(payload.fields_schema)
    ? payload.fields_schema
    : (existing.fields_schema || []),
  ...(customView ? { custom_view: customView } : {})
};

registry.trackers[trackerId] = updatedTracker;
fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2), 'utf8');

const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
if (!fs.existsSync(dataFilePath)) {
  fs.writeFileSync(dataFilePath, JSON.stringify([], null, 2), 'utf8');
}

return JSON.stringify({
  status: 'success',
  tracker_id: trackerId,
  schema: updatedTracker,
  data_file: `data_${trackerId}.json`
});

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for mutate_tracker_record', details: err.message });
}

const trackerId = String(payload.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
if (!trackerId) {
  return JSON.stringify({ error: 'tracker_id is required' });
}

const registry = fs.existsSync(registryPath)
  ? JSON.parse(fs.readFileSync(registryPath, 'utf8'))
  : { trackers: {} };
const tracker = registry.trackers?.[trackerId];
if (!tracker) {
  return JSON.stringify({ error: `Tracker '${trackerId}' not found in trackers_registry.json` });
}

const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
const records = fs.existsSync(dataFilePath)
  ? JSON.parse(fs.readFileSync(dataFilePath, 'utf8'))
  : [];

const nowIso = new Date().toISOString();
const today = nowIso.slice(0, 10);
const op = payload.operation || 'insert';

if (['advance_cycle', 'skip_or_shift_cycle', 'set_cycle_index'].includes(op)) {
  if (!tracker.cycle_config || !Array.isArray(tracker.cycle_config.steps) || tracker.cycle_config.steps.length === 0) {
    return JSON.stringify({ error: `Tracker '${trackerId}' has no valid cycle_config.steps` });
  }
  const steps = tracker.cycle_config.steps;
  const prevIndex = Number(tracker.cycle_config.current_index || 0);
  let nextIndex = prevIndex;

  if (op === 'set_cycle_index' && typeof payload.target_index === 'number') {
    nextIndex = ((payload.target_index % steps.length) + steps.length) % steps.length;
  } else {
    const defaultDelta = op === 'skip_or_shift_cycle' ? 0 : 1;
    const delta = typeof payload.step_delta === 'number' ? payload.step_delta : defaultDelta;
    nextIndex = ((prevIndex + delta) % steps.length + steps.length) % steps.length;
  }

  tracker.cycle_config.current_index = nextIndex;
  tracker.cycle_config.last_updated = today;
  registry.trackers[trackerId] = tracker;
  fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2), 'utf8');

  const logEntry = {
    id: crypto.randomUUID(),
    event: op,
    previous_step: steps[prevIndex],
    current_step: steps[nextIndex],
    ...(payload.record_data || {}),
    created_at: nowIso,
    updated_at: nowIso
  };
  records.push(logEntry);
  fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');

  return JSON.stringify({
    status: 'success',
    operation: op,
    tracker_id: trackerId,
    previous_step: steps[prevIndex],
    current_index: nextIndex,
    current_step: steps[nextIndex],
    log_entry: logEntry
  });
}

if (op === 'delete') {
  if (!payload.record_id) {
    return JSON.stringify({ error: 'record_id is required for operation delete' });
  }
  const idx = records.findIndex((r) => r.id === payload.record_id);
  if (idx === -1) {
    return JSON.stringify({ error: `Record '${payload.record_id}' not found in data_${trackerId}.json` });
  }
  const [deletedRecord] = records.splice(idx, 1);
  fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');
  return JSON.stringify({
    status: 'success',
    operation: 'delete',
    tracker_id: trackerId,
    deleted_record_id: payload.record_id,
    deleted_record: deletedRecord
  });
}

if (op === 'update' && payload.record_id) {
  const idx = records.findIndex((r) => r.id === payload.record_id);
  if (idx === -1) {
    return JSON.stringify({ error: `Record '${payload.record_id}' not found in data_${trackerId}.json` });
  }
  records[idx] = {
    ...records[idx],
    ...(payload.record_data || {}),
    id: records[idx].id,
    created_at: records[idx].created_at,
    updated_at: nowIso
  };
  fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');
  return JSON.stringify({ status: 'success', operation: 'update', record: records[idx] });
}

const newRecord = {
  id: crypto.randomUUID(),
  ...(payload.record_data || {}),
  created_at: nowIso,
  updated_at: nowIso
};
records.push(newRecord);
fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');

return JSON.stringify({
  status: 'success',
  operation: 'insert',
  tracker_id: trackerId,
  record: newRecord
});

const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for query_tracker_records', details: err.message });
}

const trackerId = String(payload.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
if (!trackerId) {
  return JSON.stringify({ error: 'tracker_id is required' });
}

const registry = fs.existsSync(registryPath)
  ? JSON.parse(fs.readFileSync(registryPath, 'utf8'))
  : { trackers: {} };
const tracker = registry.trackers?.[trackerId] || null;

const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
let records = fs.existsSync(dataFilePath)
  ? JSON.parse(fs.readFileSync(dataFilePath, 'utf8'))
  : [];

const nowMs = Date.now();
const dayMs = 24 * 60 * 60 * 1000;

if (payload.status) {
  const targetStatus = String(payload.status).toLowerCase();
  records = records.filter((r) => String(r.status || '').toLowerCase() === targetStatus);
}

if (typeof payload.older_than_days === 'number') {
  const cutoffMs = nowMs - payload.older_than_days * dayMs;
  records = records.filter((r) => {
    const refDate = Date.parse(r.updated_at || r.created_at || r.date || '');
    return !Number.isNaN(refDate) && refDate <= cutoffMs;
  });
}

if (typeof payload.recent_days === 'number') {
  const cutoffMs = nowMs - payload.recent_days * dayMs;
  records = records.filter((r) => {
    const refDate = Date.parse(r.created_at || r.updated_at || r.date || '');
    return !Number.isNaN(refDate) && refDate >= cutoffMs;
  });
}

const limit = typeof payload.limit === 'number' && payload.limit > 0 ? payload.limit : 50;
const resultRecords = records.slice(-limit);

return JSON.stringify({
  status: 'success',
  tracker_id: trackerId,
  tracker_definition: tracker,
  count: resultRecords.length,
  records: resultRecords
});

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const userDataDir = '/home/node/user_data';
const memoryPath = path.join(userDataDir, 'memory_rules.json');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for update_memory_rule', details: err.message });
}

const memory = fs.existsSync(memoryPath)
  ? JSON.parse(fs.readFileSync(memoryPath, 'utf8'))
  : { morning_rules: [], custom_scopes: {} };

if (!Array.isArray(memory.morning_rules)) memory.morning_rules = [];
if (!memory.custom_scopes || typeof memory.custom_scopes !== 'object') memory.custom_scopes = {};

const op = payload.operation || 'add';
const scope = String(payload.scope || 'morning_rules').trim();
const nowIso = new Date().toISOString();

const targetArray = scope === 'morning_rules'
  ? memory.morning_rules
  : (memory.custom_scopes[scope] = Array.isArray(memory.custom_scopes[scope]) ? memory.custom_scopes[scope] : []);

if (op === 'delete') {
  const beforeLen = targetArray.length;
  const filtered = targetArray.filter((r) => r.id !== payload.rule_id && r.instruction !== payload.instruction);
  if (scope === 'morning_rules') {
    memory.morning_rules = filtered;
  } else {
    memory.custom_scopes[scope] = filtered;
  }
  fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');
  return JSON.stringify({
    status: 'success',
    operation: 'delete',
    scope,
    deleted_count: beforeLen - filtered.length
  });
}

if (op === 'update' && payload.rule_id) {
  const idx = targetArray.findIndex((r) => r.id === payload.rule_id);
  if (idx === -1) {
    return JSON.stringify({ error: `Rule '${payload.rule_id}' not found in scope '${scope}'` });
  }
  targetArray[idx] = {
    ...targetArray[idx],
    instruction: payload.instruction || targetArray[idx].instruction,
    ...(scope !== 'morning_rules'
      ? {
          volatile: payload.volatile !== undefined ? Boolean(payload.volatile) : Boolean(targetArray[idx].volatile),
          expires_at: payload.expires_at !== undefined ? payload.expires_at : targetArray[idx].expires_at
        }
      : {})
  };
  fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');
  return JSON.stringify({ status: 'success', operation: 'update', scope, rule: targetArray[idx] });
}

const newRule = scope === 'morning_rules'
  ? {
      id: crypto.randomUUID(),
      instruction: String(payload.instruction || ''),
      created_at: nowIso
    }
  : {
      id: crypto.randomUUID(),
      instruction: String(payload.instruction || ''),
      volatile: Boolean(payload.volatile),
      expires_at: payload.expires_at || null,
      created_at: nowIso
    };

targetArray.push(newRule);
fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');

return JSON.stringify({
  status: 'success',
  operation: 'add',
  scope,
  rule: newRule
});

const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');

function sanitizeHtml(raw) {
  return String(raw || '')
    .slice(0, 24576)
    .replace(/<(script|iframe|object|embed|link|meta|base|applet)\b[^>]*>[\s\S]*?<\/\1>/gi, '')
    .replace(/<\/?(script|iframe|object|embed|link|meta|base|applet)\b[^>]*\/?>/gi, '')
    .replace(/(javascript|vbscript|data\s*:\s*text\/html)\s*:/gi, 'blocked:')
    .trim();
}

function sanitizeCss(raw) {
  return String(raw || '')
    .slice(0, 12288)
    .replace(/@import\b[^;]*;?/gi, '')
    .replace(/expression\s*\([^)]*\)/gi, '')
    .replace(/url\s*\(\s*['"]?\s*(https?:|\/\/|javascript:|vbscript:|data\s*:\s*text\/html)[^)]*\)/gi, 'url()')
    .replace(/<\/?style\b[^>]*>/gi, '')
    .trim();
}

function sanitizeJs(raw) {
  return String(raw || '')
    .slice(0, 24576)
    .replace(/<\/?script\b[^>]*>/gi, '')
    .trim();
}

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for update_tracker_custom_view', details: err.message });
}

const trackerId = String(payload.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
if (!trackerId) {
  return JSON.stringify({ error: 'tracker_id is required' });
}

const registry = fs.existsSync(registryPath)
  ? JSON.parse(fs.readFileSync(registryPath, 'utf8'))
  : { trackers: {} };

const tracker = registry.trackers?.[trackerId];
if (!tracker) {
  return JSON.stringify({ error: `Tracker '${trackerId}' not found in trackers_registry.json` });
}

const availableFields = Array.isArray(tracker.fields_schema)
  ? tracker.fields_schema.map((f) => f.name).filter(Boolean)
  : [];
const action = String(payload.action || 'set').toLowerCase();
const nowIso = new Date().toISOString();

if (action === 'reset') {
  delete tracker.custom_view;
  registry.trackers[trackerId] = tracker;
  fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2), 'utf8');
  return JSON.stringify({
    status: 'success',
    action: 'reset',
    tracker_id: trackerId,
    available_fields: availableFields,
    custom_view: null
  });
}

const sanitizedHtml = sanitizeHtml(payload.html || '<div id="app"></div>');
const sanitizedCss = sanitizeCss(payload.css || '');
const sanitizedJs = sanitizeJs(payload.js || '');

if (sanitizedJs) {
  try {
    new Function('jarvis', sanitizedJs);
  } catch (err) {
    return JSON.stringify({
      status: 'error',
      error: 'Erreur de syntaxe JS : ' + err.message + '. Corrige le JS et rappelle l\'outil.',
      tracker_id: trackerId,
      available_fields: availableFields
    });
  }
}

tracker.custom_view = {
  enabled: true,
  html: sanitizedHtml,
  css: sanitizedCss,
  js: sanitizedJs,
  updated_at: nowIso
};

registry.trackers[trackerId] = tracker;
fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2), 'utf8');

return JSON.stringify({
  status: 'success',
