const https = require('https');
const { URL } = require('url');

const agentOutput = $input.first().json.output || '';
const contextData = $('Load Runtime Context').first().json || {};
const notifyDiscord = contextData.notify_discord !== false;
const webhookUrl = String(typeof $env !== 'undefined' && $env.DISCORD_VOICE_LOG_WEBHOOK_URL ? $env.DISCORD_VOICE_LOG_WEBHOOK_URL : '').trim();

let discordSent = false;
let discordWarning = null;

function postDiscordWebhook(targetUrl, payloadObj) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(targetUrl);
    const bodyStr = JSON.stringify(payloadObj);
    const req = https.request(
      {
        hostname: parsed.hostname,
        port: parsed.port || 443,
        path: parsed.pathname + parsed.search,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(bodyStr)
        }
      },
      (res) => {
        let resBody = '';
        res.on('data', (chunk) => { resBody += chunk; });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve(true);
          } else {
            reject(new Error(`Discord HTTP ${res.statusCode}: ${resBody}`));
          }
        });
      }
    );
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

if (notifyDiscord && webhookUrl && webhookUrl.startsWith('http') && !webhookUrl.includes('/xxx/')) {
  try {
    await postDiscordWebhook(webhookUrl, {
      username: 'Jarvis Executive Voice',
      content: `🎙️ **Commande vocale traitée**\n> ${contextData.voice_command || '(commande)'}\n\n${agentOutput}`
    });
    discordSent = true;
  } catch (err) {
    discordWarning = err.message;
  }
} else if (notifyDiscord && (!webhookUrl || webhookUrl.includes('/xxx/'))) {
  discordWarning = 'DISCORD_VOICE_LOG_WEBHOOK_URL not configured or placeholder';
}

return [
  {
    json: {
      status: 'ok',
      reply: agentOutput,
      discord_sent: discordSent,
      ...(discordWarning ? { discord_warning: discordWarning } : {}),
      timestamp: new Date().toISOString()
    }
  }
];
